// SONDA DE REABERTURA DO MERCADO LIVRE -- nasceu em 28/07/2026.
//
// *** 06/10/2026 -- RELIGADA, AGORA A CADA 3H. A fonte passou a
// redirecionar o EnxameBot para /gz/account-verification ("acesse sua conta", um
// CAPTCHA de trafego suspeito); o enxame-api devolve HTTP 451 (parada etica) e o coletor
// 5vSP1WtLKpTTVBn6 foi despublicado depois de 3 rodadas perdidas (06/10, 06:00 a 18:00
// BRT). Nao se contorna a verificacao: esta sonda so pergunta se a pagina voltou a
// servir produto ao MESMO cracha. Quando voltar, o coletor e republicado.
// Criterio conferido nos dois sentidos em 06/10: a pagina de verificacao da 0 IDs e 0
// precos (execucao 4863); a pagina saudavel de 29/09 (02_Dados/raw/ml_http500_20260929)
// da 354 IDs e 533 precos -- o limiar de 20 fica longe dos dois.
//
// POR QUE EXISTE: o coletor do ML foi despublicado em 25/07 porque a fonte
// passou a servir dado APENAS a quem se apresenta como navegador. A decisao de
// nao mentir sobre a identidade nao muda -- mas, ate hoje, NINGUEM vigiava se a
// fonte tinha voltado atras. O alerta de coletor parado nao cobre o ML de
// proposito (senao gritaria todo dia sobre uma parada conhecida), entao a serie
// seguiria parada por uma escolha que talvez ja tivesse deixado de existir.
//
// ETICA: a requisicao passa ANTES pelo Agente 1 (no anterior), que le o
// robots.txt para o EnxameBot. Se ele negar, esta sonda NAO busca -- e mesmo
// assim emite diagnostico. A rota e a GERAL (/mais-vendidos/), permitida; a
// por categoria (/mais-vendidos/MLB...) e proibida e nao se toca nela.
//
// ESTE NO SEMPRE EMITE, mesmo quando nada mudou: monitor que nao mostra nada
// quando esta tudo igual e indistinguivel de monitor morto (licao de 25/07).
// Quem decide enviar e o Filtro seguinte.
const NL = String.fromCharCode(10);
const LIMIAR_IDS = 20;
const LIMIAR_PRECOS = 20;

let permitido = false;
let motivo = 'nao foi possivel ler o veredito do Agente 1';
try {
  const v = $('Agente 1: robots permite?').first().json;
  permitido = v.permitido === true;
  motivo = v.motivo || (permitido ? 'permitido' : 'negado');
} catch (e) { permitido = false; }

let html = '';
let buscou = false;
try {
  const r = $('Buscar mais-vendidos').first().json;
  html = (r && (r.data || r.body)) || '';
  if (typeof html !== 'string') { html = JSON.stringify(html); }
  buscou = true;
} catch (e) { buscou = false; }

const ids = new Set(html.match(/MLB\d{6,}/g) || []);
const precos = (html.match(/R\$/g) || []).length;
const voltou = buscou && ids.size >= LIMIAR_IDS && precos >= LIMIAR_PRECOS;
const verificacao = html.indexOf('account-verification') >= 0;

// O limiar e 20 e o numero tem motivo: quando o coletor estava saudavel a
// pagina trazia ~157 produtos; hoje ela devolve ZERO ao cracha honesto. 20 esta
// longe dos dois extremos, entao nem pagina parcial dispara nem retorno real
// passa batido.
let txt = '';
if (voltou) {
  txt = '*ENXAME - o Mercado Livre voltou a servir produto*' + NL + NL;
  txt += 'A rota /mais-vendidos/ devolveu ' + ids.size + ' IDs MLB distintos e ';
  txt += precos + ' ocorrencias de preco ao cracha honesto (EnxameBot).' + NL + NL;
  txt += 'Desde 06/10/2026 06:00 BRT ela pedia verificacao de conta (CAPTCHA).' + NL + NL;
  txt += 'Para voltar a coletar:' + NL;
  txt += '1. Republicar o Coletor Mercado Livre (5vSP1WtLKpTTVBn6).' + NL;
  txt += '2. No Alerta de Coletor Parado, voltar o ML para monitorar: true.' + NL;
  txt += '3. Despublicar esta sonda (senao ela repete o aviso a cada 3h).' + NL + NL;
  txt += 'Verificado em ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC.';
}

return [{ json: {
  avisar: voltou,
  fonte: 'mercadolivre',
  rota: 'https://www.mercadolivre.com.br/mais-vendidos/',
  cracha: 'EnxameBot/0.1 (+https://automatize-ai.tech)',
  agente1_permitido: permitido,
  agente1_motivo: motivo,
  buscou: buscou,
  bytes: html.length,
  ids_mlb_distintos: ids.size,
  ocorrencias_de_preco: precos,
  limiar_ids: LIMIAR_IDS,
  limiar_precos: LIMIAR_PRECOS,
  estado: !permitido ? 'robots negou -- nao buscamos'
        : !buscou ? 'busca falhou (rede ou bloqueio)'
        : voltou ? 'VOLTOU A TER PRODUTO'
        : verificacao ? 'segue pedindo verificacao de conta (CAPTCHA)'
        : 'segue servindo casca ao cracha honesto',
  pagina_de_verificacao: verificacao,
  verificado_em: new Date().toISOString(),
  mensagem: txt
} }];
